(()=>{
'use strict';
const APP='synthia-artifact-foundry-v1';
if(window.__SYNTHIA_ARTIFACT_FOUNDRY__) return;
window.__SYNTHIA_ARTIFACT_FOUNDRY__={version:'1.0.0'};
const td=new TextDecoder(), te=new TextEncoder();
const state={archives:[],current:null,files:[],filter:'',selected:new Set()};
function q(s,r=document){return r.querySelector(s)}
function el(tag,attrs={},children=[]){const n=document.createElement(tag);for(const[k,v]of Object.entries(attrs)){if(k==='class')n.className=v;else if(k==='text')n.textContent=v;else if(k.startsWith('on')&&typeof v==='function')n.addEventListener(k.slice(2).toLowerCase(),v);else n.setAttribute(k,v)};for(const c of [].concat(children||[]))n.append(c?.nodeType?c:document.createTextNode(String(c??'')));return n}
function u16(a,o){return a[o]|(a[o+1]<<8)} function u32(a,o){return (a[o]|a[o+1]<<8|a[o+2]<<16|a[o+3]<<24)>>>0}
function w16(a,o,v){a[o]=v&255;a[o+1]=(v>>>8)&255} function w32(a,o,v){a[o]=v&255;a[o+1]=(v>>>8)&255;a[o+2]=(v>>>16)&255;a[o+3]=(v>>>24)&255}
let crcTable=null;function crc32(a){if(!crcTable){crcTable=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;crcTable[n]=c>>>0}}let c=0xffffffff;for(const b of a)c=crcTable[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0}
async function inflateRaw(bytes){if(typeof DecompressionStream==='undefined')throw new Error('Deflate extraction is unavailable in this WebView');const ds=new DecompressionStream('deflate-raw');return new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(ds)).arrayBuffer())}
function parseZip(buf){const a=new Uint8Array(buf);let e=-1;for(let i=a.length-22;i>=Math.max(0,a.length-65557);i--){if(u32(a,i)===0x06054b50){e=i;break}}if(e<0)throw new Error('Not a valid ZIP archive');const count=u16(a,e+10),cd=u32(a,e+16),files=[];let p=cd;for(let i=0;i<count&&p+46<=a.length;i++){if(u32(a,p)!==0x02014b50)break;const method=u16(a,p+10),crc=u32(a,p+16),cs=u32(a,p+20),us=u32(a,p+24),nl=u16(a,p+28),xl=u16(a,p+30),cl=u16(a,p+32),lho=u32(a,p+42),name=td.decode(a.subarray(p+46,p+46+nl));files.push({name,method,crc,compressedSize:cs,size:us,localHeaderOffset:lho,directory:name.endsWith('/')});p+=46+nl+xl+cl}return{bytes:a,files}}
async function extractEntry(zip,f){const a=zip.bytes,o=f.localHeaderOffset;if(u32(a,o)!==0x04034b50)throw new Error('Bad ZIP local header');const nl=u16(a,o+26),xl=u16(a,o+28),start=o+30+nl+xl,comp=a.subarray(start,start+f.compressedSize);if(f.method===0)return comp;if(f.method===8)return inflateRaw(comp);throw new Error('Unsupported ZIP compression method '+f.method)}
function ext(n){const x=n.split('/').pop()||'';return(x.includes('.')?x.split('.').pop():'').toLowerCase()}
function kind(files){const names=new Set(files.map(f=>f.name.toLowerCase()));const has=s=>[...names].some(n=>n.endsWith(s));if(has('androidmanifest.xml')||has('build.gradle')||has('settings.gradle'))return'Android app';if(has('package.json')){if(has('vite.config.ts')||has('vite.config.js'))return'Vite/JavaScript app';if(has('next.config.js')||has('next.config.mjs'))return'Next.js app';return'JavaScript/Node project'}if(has('requirements.txt')||has('pyproject.toml'))return'Python project';if(has('cargo.toml'))return'Rust project';if(has('index.html'))return'Web project';return'Mixed archive'}
async function digest(bytes){const d=await crypto.subtle.digest('SHA-256',bytes);return[...new Uint8Array(d)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function openArchive(file,source='local'){const buf=await file.arrayBuffer();const zip=parseZip(buf),hash=await digest(buf),info={id:hash.slice(0,16),name:file.name,size:file.size||buf.byteLength,hash,type:kind(zip.files),source,created:Date.now(),zip};state.archives.unshift(info);state.current=info;state.files=zip.files;await remember(info);render();return info}
function db(){return new Promise((ok,bad)=>{const r=indexedDB.open(APP,1);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('archives'))d.createObjectStore('archives',{keyPath:'id'})};r.onsuccess=()=>ok(r.result);r.onerror=()=>bad(r.error)})}
async function remember(x){try{const d=await db(),t=d.transaction('archives','readwrite');t.objectStore('archives').put({id:x.id,name:x.name,size:x.size,hash:x.hash,type:x.type,source:x.source,created:x.created});await new Promise((ok,bad)=>{t.oncomplete=ok;t.onerror=()=>bad(t.error)});d.close()}catch{}}
async function history(){try{const d=await db(),t=d.transaction('archives','readonly'),r=t.objectStore('archives').getAll();const rows=await new Promise((ok,bad)=>{r.onsuccess=()=>ok(r.result||[]);r.onerror=()=>bad(r.error)});d.close();return rows.sort((a,b)=>b.created-a.created)}catch{return[]}}
function human(n){if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';return(n/1048576).toFixed(1)+' MB'}
function concat(parts){let n=parts.reduce((s,p)=>s+p.length,0),o=0,out=new Uint8Array(n);for(const p of parts){out.set(p,o);o+=p.length}return out}
async function buildStoredZip(entries){const locals=[],centrals=[];let offset=0;for(const e of entries){const name=te.encode(e.name),data=e.data instanceof Uint8Array?e.data:new Uint8Array(e.data),crc=crc32(data);const l=new Uint8Array(30+name.length);w32(l,0,0x04034b50);w16(l,4,20);w16(l,6,0x0800);w16(l,8,0);w32(l,14,crc);w32(l,18,data.length);w32(l,22,data.length);w16(l,26,name.length);l.set(name,30);locals.push(l,data);const c=new Uint8Array(46+name.length);w32(c,0,0x02014b50);w16(c,4,20);w16(c,6,20);w16(c,8,0x0800);w16(c,10,0);w32(c,16,crc);w32(c,20,data.length);w32(c,24,data.length);w16(c,28,name.length);w32(c,42,offset);c.set(name,46);centrals.push(c);offset+=l.length+data.length}const central=concat(centrals),body=concat(locals),end=new Uint8Array(22);w32(end,0,0x06054b50);w16(end,8,entries.length);w16(end,10,entries.length);w32(end,12,central.length);w32(end,16,body.length);return concat([body,central,end])}
async function mergeSelected(){const chosen=state.archives.filter(a=>state.selected.has(a.id));if(chosen.length<2)throw new Error('Select at least two loaded ZIPs');const map=new Map(),dupes=[];for(const a of chosen){for(const f of a.zip.files){if(f.directory)continue;const data=await extractEntry(a.zip,f),h=await digest(data);if(map.has(f.name)){const old=map.get(f.name);if(old.hash===h){dupes.push(f.name);continue}let base=f.name,ix=2;while(map.has(base)){const dot=f.name.lastIndexOf('.');base=dot>f.name.lastIndexOf('/')?f.name.slice(0,dot)+`-${ix++}`+f.name.slice(dot):f.name+`-${ix++}`}map.set(base,{name:base,data,hash:h})}else map.set(f.name,{name:f.name,data,hash:h})}}const out=await buildStoredZip([...map.values()]);saveBlob(new Blob([out],{type:'application/zip'}),'synthia-stitched-'+Date.now()+'.zip');notice(`Stitched ${map.size} files; skipped ${dupes.length} byte-identical duplicate${dupes.length===1?'':'s'}.`)}
function saveBlob(blob,name){const u=URL.createObjectURL(blob),a=el('a',{href:u,download:name});document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(u);a.remove()},1000)}
async function preview(f){if(!state.current)return;const data=await extractEntry(state.current.zip,f),x=ext(f.name);if(data.length>1024*1024)throw new Error('Preview limited to 1 MB');const textish=['js','mjs','cjs','ts','tsx','jsx','json','html','css','md','txt','xml','yml','yaml','py','java','kt','gradle','sh','c','cpp','h'].includes(x);if(!textish)throw new Error('Binary preview is not shown');q('#saf-preview-title').textContent=f.name;q('#saf-preview-body').textContent=td.decode(data);q('#saf-preview').hidden=false}
function notice(msg,bad=false){const n=q('#saf-note');n.textContent=msg;n.style.color=bad?'#fca5a5':'#a7f3d0';setTimeout(()=>{if(n.textContent===msg)n.textContent=''},5000)}
function css(){return `#saf-btn{position:fixed;right:14px;bottom:76px;z-index:2147482000;width:46px;height:46px;border-radius:14px;border:1px solid rgba(255,255,255,.16);background:#17121d;color:#f7eefa;box-shadow:0 10px 30px #0009;font:700 20px system-ui}#saf{position:fixed;inset:0;z-index:2147482500;background:#09070de8;backdrop-filter:blur(8px);display:none;color:#f4eef7;font:13px/1.4 system-ui}#saf.open{display:block}#saf *{box-sizing:border-box}#saf-card{width:min(980px,calc(100% - 18px));height:min(86vh,760px);margin:7vh auto;background:#141019;border:1px solid #3b2d46;border-radius:18px;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 30px 80px #000a}#saf-head{padding:13px 16px;display:flex;align-items:center;gap:10px;border-bottom:1px solid #2d2235}#saf-head b{font-size:16px}#saf-head span{color:#aa9ab4}.saf-sp{flex:1}.saf-b{border:1px solid #443450;background:#211827;color:#f4eef7;border-radius:10px;padding:8px 10px}.saf-b:active{transform:scale(.97)}#saf-main{display:grid;grid-template-columns:260px 1fr;flex:1;min-height:0}#saf-side{border-right:1px solid #2d2235;padding:10px;overflow:auto}#saf-files{overflow:auto;padding:10px}.saf-a{padding:9px;border:1px solid #302439;border-radius:10px;margin-bottom:7px;background:#18121e}.saf-a strong{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.saf-meta{font-size:11px;color:#a998b4}.saf-file{width:100%;display:grid;grid-template-columns:1fr auto;gap:8px;text-align:left;padding:8px;border:0;border-bottom:1px solid #241b2b;background:transparent;color:#eee}.saf-file:hover{background:#1b1421}.saf-name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}#saf-tools{padding:10px;border-bottom:1px solid #2d2235;display:flex;gap:8px;align-items:center;flex-wrap:wrap}#saf-filter{flex:1;min-width:160px;background:#0d0a11;color:#eee;border:1px solid #3b2d46;border-radius:10px;padding:8px}#saf-note{min-height:18px;padding:0 12px 8px}#saf-preview{position:absolute;inset:5%;background:#0d0a11;border:1px solid #503d5e;border-radius:14px;z-index:2;display:flex;flex-direction:column;box-shadow:0 20px 60px #000}#saf-preview[hidden]{display:none}#saf-preview pre{flex:1;overflow:auto;margin:0;padding:12px;white-space:pre-wrap;font:12px/1.4 monospace}#saf-preview-title{padding:10px;border-bottom:1px solid #302439;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}@media(max-width:700px){#saf-main{grid-template-columns:1fr}#saf-side{max-height:170px;border-right:0;border-bottom:1px solid #2d2235}#saf-card{height:92vh;margin:4vh auto}}`}
function shell(){const s=el('style',{text:css()}),btn=el('button',{id:'saf-btn',title:'Artifact Foundry',text:'◇',onclick:()=>q('#saf').classList.add('open')}),root=el('div',{id:'saf'});root.innerHTML=`<div id="saf-card"><div id="saf-head"><b>Artifact Foundry</b><span>inspect · dedupe · stitch</span><i class="saf-sp"></i><button class="saf-b" id="saf-pick">Add ZIP</button><button class="saf-b" id="saf-close">×</button></div><div id="saf-main"><aside id="saf-side"></aside><section style="min-width:0;display:flex;flex-direction:column;position:relative"><div id="saf-tools"><input id="saf-filter" placeholder="Filter files…"><button class="saf-b" id="saf-merge">Stitch selected</button></div><div id="saf-note"></div><div id="saf-files"></div><div id="saf-preview" hidden><div style="display:flex;align-items:center"><div id="saf-preview-title" style="flex:1"></div><button class="saf-b" id="saf-preview-close">×</button></div><pre id="saf-preview-body"></pre></div></section></div></div>`;const inp=el('input',{type:'file',accept:'.zip,application/zip',multiple:'',style:'display:none'});document.head.append(s);document.body.append(btn,root,inp);q('#saf-close').onclick=()=>root.classList.remove('open');q('#saf-preview-close').onclick=()=>q('#saf-preview').hidden=true;q('#saf-pick').onclick=()=>inp.click();inp.onchange=async()=>{for(const f of inp.files||[])try{await openArchive(f)}catch(e){notice(e.message,true)}inp.value=''};q('#saf-filter').oninput=e=>{state.filter=e.target.value.toLowerCase();renderFiles()};q('#saf-merge').onclick=()=>mergeSelected().catch(e=>notice(e.message,true));render()}
function render(){const side=q('#saf-side');if(!side)return;side.innerHTML='';if(!state.archives.length)side.append(el('div',{class:'saf-meta',text:'Add ZIP projects from your phone. Everything is analyzed locally.'}));for(const a of state.archives){const c=el('div',{class:'saf-a'}),row=el('div',{style:'display:flex;gap:7px'}),ck=el('input',{type:'checkbox'});ck.checked=state.selected.has(a.id);ck.onchange=()=>ck.checked?state.selected.add(a.id):state.selected.delete(a.id);const name=el('button',{style:'all:unset;cursor:pointer;min-width:0;flex:1'});name.append(el('strong',{text:a.name}),el('div',{class:'saf-meta',text:`${a.type} · ${a.zip.files.filter(f=>!f.directory).length} files · ${human(a.size)}`}),el('div',{class:'saf-meta',text:a.hash.slice(0,12)}));name.onclick=()=>{state.current=a;state.files=a.zip.files;renderFiles()};row.append(ck,name);c.append(row);side.append(c)}renderFiles()}
function renderFiles(){const box=q('#saf-files');if(!box)return;box.innerHTML='';if(!state.current){box.append(el('div',{class:'saf-meta',text:'No archive open.'}));return}const fs=state.files.filter(f=>!f.directory&&(!state.filter||f.name.toLowerCase().includes(state.filter)));for(const f of fs.slice(0,2500)){const b=el('button',{class:'saf-file',onclick:()=>preview(f).catch(e=>notice(e.message,true))});b.append(el('span',{class:'saf-name',text:f.name}),el('span',{class:'saf-meta',text:human(f.size)}));box.append(b)}if(fs.length>2500)box.append(el('div',{class:'saf-meta',text:`Showing 2500 of ${fs.length} files.`}))}
function boot(){if(document.body)shell();else addEventListener('DOMContentLoaded',shell,{once:true})}
boot();
})();
